def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for v in row:
            if v:
                freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)
    color = next(v for v in freq if v != bg)
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    out = [row[:] for row in grid]

    # Expand the seed color into nearby empty cells, stopping at the
    # dominant background cells. Only empty cells connected to the seed
    # through empty cells are filled.
    q = deque()
    seen = set()
    for r, c in seeds:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            y, x = r + dr, c + dc
            if 0 <= y < h and 0 <= x < w and grid[y][x] == 0:
                q.append((y, x))
                seen.add((y, x))
    while q:
        r, c = q.popleft()
        out[r][c] = color
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            y, x = r + dr, c + dc
            if 0 <= y < h and 0 <= x < w and grid[y][x] == 0 and (y, x) not in seen:
                seen.add((y, x))
                q.append((y, x))
    return out
